import json, sys

path = sys.argv[1]
maxlen = int(sys.argv[2]) if len(sys.argv) > 2 else 300

with open(path) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            print(f"[{i}] PARSE ERROR: {e}")
            continue
        ts = obj.get("timestamp", "")
        typ = obj.get("type", "")
        msg = obj.get("message")
        out = f"[{i}] ts={ts} type={typ}"
        if "attachment" in obj:
            att = obj["attachment"]
            content = att.get("content") or att.get("stdout") or ""
            out += f" hook={att.get('hookName')} content={content[:maxlen]!r}"
        elif isinstance(msg, dict):
            role = msg.get("role")
            content = msg.get("content")
            pieces = []
            if isinstance(content, str):
                pieces.append(content[:maxlen])
            elif isinstance(content, list):
                for c in content:
                    ctype = c.get("type")
                    if ctype == "text":
                        pieces.append(f"TEXT: {c.get('text','')[:maxlen]}")
                    elif ctype == "tool_use":
                        pieces.append(f"TOOL_USE {c.get('name')}: {json.dumps(c.get('input',{}))[:maxlen]}")
                    elif ctype == "tool_result":
                        cc = c.get("content")
                        if isinstance(cc, list):
                            cc = " ".join(x.get("text","") for x in cc if isinstance(x, dict))
                        pieces.append(f"TOOL_RESULT: {str(cc)[:maxlen]}")
                    else:
                        pieces.append(f"{ctype}: {str(c)[:maxlen]}")
            out += f" role={role} :: " + " | ".join(pieces)
        print(out)

